    await wait(500);
    const after = { cls: el.className, top: Math.round(el.getBoundingClientRect().top) };
    document.getElementById('preview').scrollIntoView({behavior:'instant', block:'start'});
    await wait(800);
    const back = { cls: el.className, top: Math.round(el.getBoundingClientRect().top) };
    io.disconnect();
    return { before, after, back, log };
  })()`
})
return res.value

